def forward(self, after: int, through: int):
    with self.path.open('rb') as stream:
        stream.seek(after)
        while stream.tell() < through:
            start = stream.tell()
            raw = stream.readline(through - start)
            if not raw:
                return
            yield NativeRecord.read(start, stream.tell(), raw)

