@classmethod
def capture(cls, root: Path, registry_path: Path, document: RegistryDocument, declaration):
    """Caller owns the original read/writer throughout proof acquisition."""
    root = root.resolve()
    log = WireLog(root / 'bus.jsonl')
    bus_revision = FileRevision.capture(log.path)
    registry_revision = FileRevision.capture(registry_path)
    marker = log.read_metadata_unlocked(required=True)
    provenance = cls.project(document, declaration)
    info = log.path.stat()
    if bus_revision != FileRevision.capture(log.path) or registry_revision != FileRevision.capture(registry_path):
        raise ValueError('Original recorded source changed during acquisition')
    return cls(str(root), str(root), marker.root_id, (info.st_dev, info.st_ino), info.st_size, bus_revision, registry_revision, provenance)

def main():
    root, descriptor, root_id, receipt = sys.argv[1:]
    root, plan = read_plan(root, descriptor, root_id)
    receipt = Path(receipt)
    if receipt.exists():
        raise ValueError('A retained original receipt cannot be overwritten.')
    bus = require_retained_writer(root, descriptor, root_id)
    database = root / 'transcript_routes.sqlite3'
    connection_scope = closing(sqlite3.connect(database.as_uri() + '?mode=rw', uri=True)) if database.exists() else nullcontext(None)
    original_registry = (root / 'registry.json').read_text()
    registry_store = RegistryStore(root / 'registry.json')
    registry_mode = (root / 'registry.json').stat().st_mode & 511
    with connection_scope as connection:
        if connection is not None:
            connection.execute('PRAGMA synchronous=FULL')
            connection.execute('BEGIN IMMEDIATE')
        document, source = plan.require_target(root, connection)
        try:
            for cell in plan.cells:
                table = next((table for table in tables() if table.declared_name == cell.table))
                where = ' AND '.join((f'"{key}"=?' for key in cell.keys))
                encoded = json.dumps(cell.routing, separators=(',', ':'))
                changed = connection.execute(f'UPDATE "{table.declared_name}" SET routing=? WHERE {where} AND routing IS NOT NULL', (encoded, *cell.keys.values())).rowcount
                if changed != 1:
                    raise ValueError('Original routing cell was not updated exactly once.')
            for turn in plan.turns:
                document['threads'][turn.thread]['active_turn']['routing'] = turn.routing
            if plan.turns:
                registry_store._write_unlocked(json.dumps(document))
                os.chmod(root / 'registry.json', registry_mode)
            if connection is not None:
                _assert_schema(connection)
                after = {table.declared_name: [{k: v for k, v in row.items() if k != 'routing'} for row in table_rows(connection, table)] for table in tables()}
                if digest_json(after) != plan.annotation_nonrouting_digest:
                    raise ValueError('Carry changed nonrouting annotation data.')
                connection.commit()
        except BaseException:
            if connection is not None:
                connection.rollback()
            if plan.turns and (root / 'registry.json').read_text() != original_registry:
                registry_store._write_unlocked(original_registry)
                os.chmod(root / 'registry.json', registry_mode)
            raise
    witness = install_private_bus_checkpoint(bus, _bus_locked=True)
    plan.require_sources(root)
    registry = json.loads((root / 'registry.json').read_bytes())
    if digest_json(registry_without_routing(registry)) != plan.registry_nonrouting_digest:
        raise ValueError('Carry changed original nonrouting registry state.')
    if database.exists() and file_witness(database)['mode'] != plan.database['mode']:
        raise ValueError('Carry changed annotation storage mode.')
    carried_source = replace(source, snapshot_registry_revision=FileRevision.capture(root / 'registry.json'))
    carried_source.require_original(root)
    result = {'root_id': root_id, 'through_seq': witness.through_seq, 'original_writer_descriptor_verified': True, 'routing_cells': len(plan.cells), 'registry_routings': len(plan.turns), 'original_bus': plan.bus, 'protected_originals': plan.protected, 'original_certified_references': plan.originals, 'original_registry_sha256': plan.registry_digest, 'original_annotation_database': plan.database, 'carried_annotation_database': file_witness(database), 'nonrouting_annotations_unchanged': True, 'nonrouting_registry_unchanged': True, 'recorded_source': FieldCodec.encode(carried_source), 'original_input_replays': 0, 'provider_calls': 0}
    _atomic_write_text(receipt, json.dumps(result, indent=2) + '\n', fsync_parent=True)
    print(json.dumps({'receipt': str(receipt), 'routing_cells': len(plan.cells), 'registry_routings': len(plan.turns)}), flush=True)

