def bind(self, value: QueueChangedUpdate, session_id: str, token: int):
    result = super().bind(value, session_id, token)
    pending, self._pending_starts = (self._pending_starts, [])
    starts = tuple((item for fact in pending for item in self.started(fact, session_id)))
    return (result, starts)

def started(self, update: InputStartedUpdate, session_id: str) -> tuple[InputStartedUpdate, ...]:
    if update.scope is None or update.scope.session_id != session_id:
        return ()
    if self._pending:
        self._observe_floor(update.scope)
        if len(self._pending_starts) >= self.MAX_PREBIND:
            self._quarantine(uncertain=True)
        else:
            self._pending_starts.append(update)
        return ()
    if self.quarantined or self.scope is None or (not self.scope.relation(update.scope).current):
        return ()
    previous = self._last_started
    if update.input_id is None or update.text is None or update.revision is None or (previous is not None and previous.scope.relation(update.scope).current and (update.revision <= previous.revision)):
        return ()
    self._last_started = update
    return (update,)

def settle(self, presentation: ThreadPresentation | None) -> ThreadPresentation | None:
    if self.agent.observed_thread() != self.thread:
        raise ValueError('Thread attachment changed while reading status')
    if self.authority.retired:
        raise ValueError('Client session ended while reading status')
    if presentation is not None:
        self.snapshot.dispatch_sync(presentation)
    return presentation

def bind(self, value: CursorEnvelope | QueueChangedUpdate | None, session_id: str, token: int) -> str:
    if token != self._token:
        return 'reject_old_request'
    if self._evidence_lost:
        self._quarantine()
        return 'reject_evidence_lost'
    self._pending = False
    self._session_id = session_id
    envelope = value
    if envelope is None or envelope.scope is None or envelope.scope.session_id != session_id:
        self._quarantine(uncertain=True)
        return 'reject_unavailable_binding'
    scope = envelope.scope
    observed = self._prebind_floors.get((scope.logical_key, scope.owner_created_at))
    if observed is not None:
        self._observe_floor(observed)
    matching = []
    for receiving_session, buffered in self._buffer:
        other = buffered.scope
        if receiving_session != session_id or scope.relation(other).foreign:
            continue
        if scope.relation(other).ambiguous:
            self._uncertain = True
        elif scope.relation(other).newer:
            self._observe_floor(other)
        elif scope.relation(other).current:
            matching.append(buffered)
    floor = self.floor
    if self._uncertain or (floor is not None and scope.relation(floor).newer):
        self._quarantine()
        return 'reject_binding_floor_or_uncertainty'
    if self.current is not None and self.current.scope.relation(scope).current and (envelope.revision < self.current.revision or (envelope.revision == self.current.revision and envelope.digest != self.current.digest)):
        self._quarantine(uncertain=True)
        return 'reject_stale_or_conflicting_binding'
    self.current = envelope
    self.quarantined = False
    self._observe_floor(scope)
    self._buffer.clear()
    self._prebind_floors.clear()
    for buffered in sorted(matching, key=lambda item: item.revision):
        self._apply(buffered)
    return 'bind'

